# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

OPEN = Span(9 * 60, 17 * 60)


class FindGapsTests(unittest.TestCase):
    def test_gap_in_the_middle(self):
        worked = [Span(540, 720), Span(780, 1020)]
        self.assertEqual(find_gaps(worked, OPEN), ["gap 12:00-13:00 (60 min)"])

    def test_edges_and_overlaps(self):
        worked = [Span(600, 720), Span(660, 900)]
        self.assertEqual(
            find_gaps(worked, OPEN),
            ["gap 09:00-10:00 (60 min)", "gap 15:00-17:00 (120 min)"]
        )

    def test_nobody_working(self):
        self.assertEqual(find_gaps([], OPEN), ["gap 09:00-17:00 (480 min)"])

    def test_full_coverage(self):
        self.assertEqual(find_gaps([Span(540, 1020)], OPEN), [])

    def test_span_outside_opening_hours(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(480, 600)], OPEN)
        with self.assertRaises(ValueError):
            find_gaps([Span(600, 1080)], OPEN)


if __name__ == "__main__":
    unittest.main()
